__attribute__((naked)) void DoWhiteOut(void)
{
    __asm__(".syntax unified\n\t"
        ".code 16\n\t"
        "	push {r4, lr}\n\t"
        "	ldr r0, _08083FE0\n\t"
        "	bl RunScriptImmediately\n\t"
        "	ldr r0, _08083FE4\n\t"
        "	ldr r4, [r0]\n\t"
        "	movs r0, #0x92\n\t"
        "	lsls r0, r0, #3\n\t"
        "	adds r4, r4, r0\n\t"
        "	adds r0, r4, #0\n\t"
        "	bl GetMoney\n\t"
        "	adds r1, r0, #0\n\t"
        "	lsrs r1, r1, #1\n\t"
        "	adds r0, r4, #0\n\t"
        "	bl SetMoney\n\t"
        "	bl HealPlayerParty\n\t"
        "	bl Overworld_ResetStateAfterWhiteOut\n\t"
        "	bl SetWarpDestinationToLastHealLocation\n\t"
        "	bl WarpIntoMap\n\t"
        "	pop {r4}\n\t"
        "	pop {r0}\n\t"
        "	bx r0\n\t"
        "	.align 2, 0\n\t"
        "_08083FE0: .4byte EventScript_WhiteOut\n\t"
        "_08083FE4: .4byte gSaveBlock1Ptr\n\t"
        ".syntax divided\n\t"
    );
}

